  function fieldHay(b){return [b.title,b.desc,b.note,b.url].join(' ').toLowerCase();}
  function leafPred(tok){
    if(tok.kind==='tag'){
      return function(b){return (b.tags||[]).some(function(t){return t.toLowerCase().indexOf(tok.v)>=0;});};
    }
    return function(b){return fieldHay(b).indexOf(tok.v)>=0 ||
      (b.tags||[]).some(function(t){return t.toLowerCase().indexOf(tok.v)>=0;});};
  }

  // recursive-descent: OR (lowest) -> AND (implicit too) -> NOT -> primary
  function parse(toks){
    var pos=0, terms=[];
    function peek(){return toks[pos];}
    function eat(){return toks[pos++];}
    function parseOr(){
      var left=parseAnd();
      while(peek() && peek().t==='op' && peek().v==='OR'){ eat();
        var right=parseAnd(); var l=left,r=right; left=function(b){return l(b)||r(b);}; }
      return left;
    }
    function parseAnd(){
      var left=parseNot();
      while(peek() && !(peek().t==='op'&&peek().v==='OR') && peek().t!=='rp'){
        if(peek().t==='op'&&peek().v==='AND') eat(); // explicit AND
        var right=parseNot(); var l=left,r=right; left=function(b){return l(b)&&r(b);};
      }
      return left;
    }
    function parseNot(){
      if(peek() && peek().t==='op' && peek().v==='NOT'){ eat();
        var p=parseNot(); return function(b){return !p(b);}; }
      return parsePrimary();
    }
    function parsePrimary(){
      var tk=peek();
      if(!tk) return function(){return true;};
      if(tk.t==='lp'){ eat(); var e=parseOr(); if(peek()&&peek().t==='rp') eat(); return e; }
      if(tk.t==='term'){ eat(); terms.push(tk.v); return leafPred(tk); }
      eat(); return function(){return true;}; // stray op/rp
    }
    var pred=parseOr();
    return {pred:pred, terms:terms};
  }

  function buildSearch(raw){
    var q=raw.trim();
    if(!q) return {pred:function(){return true;}, terms:[], active:false};
    try{ var r=parse(tokenize(q)); return {pred:r.pred, terms:r.terms, active:true}; }
    catch(e){ var lc=q.toLowerCase();
      return {pred:function(b){return fieldHay(b).indexOf(lc)>=0;}, terms:[lc], active:true}; }
  }

  function hlMulti(text,terms){
    var s=esc(text||'');
    if(!terms||!terms.length) return s;
    terms.forEach(function(t){
      if(!t) return;
      var re=new RegExp('('+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');
      s=s.replace(re,function(m,p1,off,full){
        // avoid double-wrapping inside an existing tag/mark by simple check
        return ''+p1+'';
      });
    });
    return s.replace(//g,'<mark>').replace(//g,'</mark>');
  }

